// «Как проходит запись»: короткая полоса из трёх шагов с линией-таймлайном,
// которая ведёт взгляд к форме записи ниже. Движение lively — шаги «прошагивают»
// слева направо, линия прочерчивается по мере скролла; при prefers-reduced-motion
// всё видно сразу.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = {
  title: string;
  note: string;
};

export type StepsBookingTimelineProps = {
  title: string;
  subtitle?: string;
  steps: Step[];
  buttonLabel: string;
  anchor: string;
};

export default function StepsBookingTimeline({
  title,
  subtitle,
  steps,
  buttonLabel,
  anchor,
}: StepsBookingTimelineProps) {
  const reduced = useReducedMotion();
  const animate = !reduced;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="max-w-text min-w-0">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          {subtitle ? <p className="mt-3 text-lead text-muted-foreground">{subtitle}</p> : null}
        </div>

        <div className="relative mt-12">
          {/* Линия-таймлайн: на мобильных вертикальная, на десктопе горизонтальная */}
          <m.span
            aria-hidden="true"
            className="absolute top-5 bottom-5 left-5 w-px bg-border md:top-5 md:right-5 md:bottom-auto md:left-5 md:h-px md:w-auto"
            initial={animate ? { scaleY: 0, scaleX: 0 } : false}
            whileInView={animate ? { scaleY: 1, scaleX: 1 } : undefined}
            viewport={{ once: true, margin: "-80px" }}
            transition={{ duration: 0.7, ease: "easeOut" }}
            style={{ transformOrigin: "top left" }}
          />

          <ol className="grid grid-cols-1 gap-10 md:grid-cols-3 md:gap-8">
            {steps.map((step, i) => (
              <m.li
                key={step.title}
                className="relative flex min-w-0 gap-5 pl-14 md:block md:pl-0"
                initial={animate ? { opacity: 0, y: 24 } : false}
                whileInView={animate ? { opacity: 1, y: 0 } : undefined}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.45, delay: animate ? i * 0.18 : 0, ease: "easeOut" }}
              >
                <span
                  aria-hidden="true"
                  className="absolute top-0 left-0 flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-primary bg-card font-display text-h3 font-bold text-primary md:relative md:mb-5"
                >
                  {i + 1}
                </span>
                <div className="min-w-0">
                  <h3 className="font-display text-h3 font-bold wrap-break-word">{step.title}</h3>
                  <p className="mt-2 text-body text-muted-foreground wrap-break-word">{step.note}</p>
                </div>
              </m.li>
            ))}
          </ol>
        </div>

        <div className="mt-12">
          <a
            href={anchor}
            className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
            {buttonLabel}
          </a>
        </div>
      </div>
    </section>
  );
}

